    with pytest.raises(Exception, match="cpu_bytes_to_use must be specified"):
        _create_spec(cpu_bytes_to_use=None)

def test_duplicate_registration_raises():
    with pytest.raises(ValueError, match="is already registered"):
        OffloadingSpecFactory.register_spec(
            "CPUOffloadingSpec", "some.module", "SomeClass"
        )

def test_build_metric_definitions_returns_counter_at_threshold():
    from vllm.v1.kv_offload.cpu.common import CPUOffloadingMetrics

    extra_config = {"store_threshold": 2}
    spec_cls = OffloadingSpecFactory.get_spec_cls({"spec_name": "CPUOffloadingSpec"})
    metrics = spec_cls.build_metric_definitions(extra_config)

    assert CPUOffloadingMetrics.STORES_SKIPPED in metrics

def test_failure_threshold_only_for_storage_tiers(self, tier_type, expected):
        cfg = EMABackpressureDetector.default_config(tier_type)
        assert cfg.get("failure_threshold") == expected

def test_success_resets_failure_streak(self):
        bp = self._make_detector()
        bp._completions = _BP_WARMUP
        bp._last_update = time.monotonic()
        for _ in range(_BP_FAILURE_THRESHOLD - 1):
            bp.on_store_failed()
        self._complete_fast_store(bp)
        for _ in range(_BP_FAILURE_THRESHOLD - 1):
            bp.on_store_failed()
        assert bp.is_under_pressure() is False

def test_no_drop_when_not_under_pressure(self):
        bp = self._make_detector()
        for _ in range(20):
            assert bp.should_store(1) is True

def test_no_drop_at_exactly_high_water(self):
        bp = self._make_detector()
        bp._under_pressure = True
        bp.store_latency_ema = _BP_HIGH_WATER_S
        for _ in range(20):
            assert bp.should_store(1) is True

def test_full_drop_at_severe_pressure(self):
        bp = self._make_detector()
        bp._under_pressure = True
        bp.store_latency_ema = _BP_HIGH_WATER_S * 4
        for _ in range(20):
            assert bp.should_store(1) is False

def test_drop_count_tracks_rate(self, drop_rate):
        """After each decision, the drop count is within one store of the target."""
        bp = self._make_detector_at_rate(drop_rate)
        drops = 0
        for num_stores in range(1, 21):
            if not bp.should_store(1):
                drops += 1
            expected_drops = num_stores * drop_rate
            assert abs(drops - expected_drops) <= 1.0 + 1e-8

def test_not_healthy_initially(self):
        bp = self._make_detector()
        assert bp.is_healthy() is False

def test_no_cooldown_when_never_pressured(self):
        bp = self._make_detector()
        for _ in range(20):
            assert bp.should_store(1) is True

def test_no_cooldown_after_window_expires(self):
        bp = self._make_detector()
        bp._pressure_cleared_at = time.monotonic() - 2.0
        for _ in range(20):
            assert bp.should_store(1) is True
